static std::mt19937 gen(rd());
std::uniform_real_distribution<double> dist_prob(0.0, 1.0);
std::normal_distribution<double> dist_norm(0.0, 1.0);

const double k_B = 1.380649e-23; // Boltzmann constant (adjust based on unit system)
double sigma_sq = targetTemp * k_B;

for (std::size_t i = 0; i < velocities.size(); ++i) {
    if (dist_prob(gen) < collisionFreq * dt) {
        double std_dev = std::sqrt(2.0 * sigma_sq / masses[i]);
        velocities[i].x = dist_norm(gen) * std_dev;
        velocities[i].y = dist_norm(gen) * std_dev;
        velocities[i].z = dist_norm(gen) * std_dev;
    }
}
